@Component({
  selector: 'app-not-found',
  templateUrl: './not-found.component.html',
})
export class NotFoundComponent { }
<div class="flex flex-col items-center justify-center h-screen text-center px-4">
  <h1 class="text-5xl md:text-5xl font-semibold text-gray-100">404</h1>
  <h1 class="text-2xl md:text-3xl font-semibold mt-6">This page has not been generated</h1>
  <p class="mt-4 text-xl md:text-2xl text-gray-500">Tell me what you would like on this page</p>
</div>
